create function pg_temp.assert_true(v boolean,message text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',message;end if;end$$;
create function pg_temp.expect_error(q text,code text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=code then return;else raise;end if;end;raise exception 'Expected error % for %',code,q;end$$;
set role anon;
select pg_temp.expect_error('select public.admin_launch_snapshot(30)','42501');
reset role;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select pg_temp.expect_error('select public.admin_launch_snapshot(30)','42501');
select pg_temp.expect_error($q$select public.admin_save_launch_goal('ready_talent',100,'Team','2026-12-01',0,20)$q$,'42501');
select pg_temp.assert_true((select count(*)=0 from public.admin_launch_goals),'nonstaff sees no goals');
select pg_temp.expect_error($q$insert into public.admin_analytics_exclusions(user_id,reason) values('00000000-0000-0000-0000-000000000002','self')$q$,'42501');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select pg_temp.assert_true((public.admin_launch_snapshot(7)->>'days')::integer=7,'period supported');
select pg_temp.assert_true(public.admin_launch_snapshot(7)->'sources'->'activities'->>'error' is not null,'missing source not zero');
select public.admin_save_launch_goal('ready_talent',100,'Team','2026-12-01',0,20);
select pg_temp.assert_true((select count(*)=1 from public.admin_launch_goal_history),'first observation recorded');
select pg_temp.expect_error($q$select public.admin_save_launch_goal('ready_talent',200,'Team','2026-12-01',0,21)$q$,'PT409');
select public.admin_save_launch_goal('ready_talent',150,'Community','2026-12-15',1,null);
select pg_temp.assert_true((select version=2 from public.admin_launch_goals),'version increments');
select pg_temp.assert_true((select count(*)=2 from public.admin_launch_goal_history),'unknown observation stays null');
select pg_temp.expect_error($q$select public.admin_save_launch_goal('ready_talent',-1,'Team','2026-12-01',2,21)$q$,'23514');
select public.admin_set_analytics_exclusion('00000000-0000-0000-0000-000000000002','Test account',true);
select pg_temp.assert_true((select count(*)=1 from public.admin_analytics_exclusions),'explicit exclusion saved');
select public.admin_set_analytics_exclusion('00000000-0000-0000-0000-000000000002','',false);
select pg_temp.assert_true((select count(*)=0 from public.admin_analytics_exclusions),'exclusion reversible');
select pg_temp.expect_error($q$select public.admin_review_profile_request('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000009','approve',null)$q$,'PT409');
select pg_temp.expect_error($q$select public.admin_review_profile_request('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003','fail_after_write',null)$q$,'PT409');
reset role;
select pg_temp.assert_true((select profile_review_status='pending' from public.profiles),'failure rolls back underlying writes');
set role authenticated;
select public.admin_review_profile_request('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003','approve',null);
select pg_temp.expect_error($q$select public.admin_review_profile_request('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003','approve',null)$q$,'PT409');
select 'Admin launch database checks passed' as result;
